INSERT INTO "ArticuloConocimiento" ("id", "titulo", "problema", "sintomas", "causa", "solucion", "fecha", "estado", "verificado")
VALUES
  (1, '[Software] Equipo lento después de una actualización de Windows', 'El equipo se vuelve muy lento después de instalar una actualización de Windows.', 'Arranque de más de cinco minutos, uso de disco al 100 % en el Administrador de tareas y ventanas que tardan en abrirse.', 'Procesos de indexación y de reparación de la actualización compitiendo por el disco, o servicios de actualización en bucle.', '1) Esperar a que termine la indexación y reiniciar. 2) Ejecutar sfc /scannow y DISM /Online /Cleanup-Image /RestoreHealth. 3) Deshabilitar programas de inicio innecesarios. 4) Si persiste, revertir la actualización desde Configuración, Windows Update, Historial.', '2026-10-02 10:00:00', 'Activo', true),
  (2, '[Software] Instalación de programa rechazada por falta de permisos', 'La instalación de un programa corporativo falla con el mensaje de que no tiene permisos suficientes.', 'El instalador se cierra al iniciar o muestra error 1925 y pide credenciales de administrador.', 'El usuario no pertenece al grupo de administradores locales y la directiva de control de cuentas bloquea la elevación.', '1) Abrir la mesa de servicio con el nombre del programa. 2) El técnico ejecuta el instalador con una cuenta de soporte o lo publica desde el centro de software. 3) Verificar que el programa abre con la cuenta del usuario. 4) Registrar la versión instalada.', '2026-10-03 11:00:00', 'Activo', true),
  (3, '[Software] Pantalla azul por controlador incompatible', 'El equipo muestra una pantalla azul con el código DRIVER_IRQL_NOT_LESS_OR_EQUAL.', 'Reinicios inesperados, pantalla azul al conectar un dispositivo o al reanudar desde suspensión.', 'Controlador de red, video o almacenamiento incompatible o dañado tras una actualización.', '1) Arrancar en modo seguro. 2) Identificar el controlador en el visor de eventos o con WhoCrashed. 3) Desinstalar el controlador y reinstalar la versión del fabricante. 4) Instalar las actualizaciones de BIOS pendientes. 5) Monitorear durante 48 horas.', '2026-10-04 12:00:00', 'Activo', true),
  (4, '[Software] Actualización automática atascada en 0 por ciento', 'La actualización automática de un programa se queda atascada en 0 por ciento.', 'La barra de progreso no avanza durante horas y el botón de cancelar no responde.', 'Posible bloqueo del servicio de actualización por una descarga interrumpida; la causa aún no está confirmada.', '1) Cerrar el programa desde el Administrador de tareas. 2) Reiniciar el servicio de actualización. 3) Borrar la carpeta temporal de descargas. 4) Volver a intentar. Procedimiento pendiente de verificación por el equipo.', '2026-10-05 13:00:00', 'Activo', false),
  (5, '[Software] Antivirus envía un ejecutable interno a cuarentena', 'El antivirus bloquea un ejecutable interno y lo envía a cuarentena.', 'El programa del área contable deja de abrir y el antivirus reporta una amenaza detectada.', 'Regla de detección heurística del antivirus anterior que marcaba como sospechoso un ejecutable sin firma.', '1) Restaurar el archivo desde cuarentena. 2) Agregar una exclusión por ruta. 3) Informar a seguridad. Artículo inactivo: el antivirus fue reemplazado y la exclusión ya no aplica.', '2026-10-06 14:00:00', 'Inactivo', true),
  (6, '[Hardware] Equipo de escritorio que no enciende', 'El equipo de escritorio no enciende al presionar el botón de poder.', 'No hay luces ni ventiladores, o las luces encienden y se apagan de inmediato.', 'Cable de alimentación flojo, regleta apagada o fuente de poder dañada.', '1) Verificar el cable y la regleta con otro dispositivo. 2) Mantener presionado el botón de poder 30 segundos con el cable desconectado. 3) Probar con una fuente de repuesto. 4) Si no enciende, abrir orden de reparación y registrar el número de serie.', '2026-10-07 09:00:00', 'Activo', true),
  (7, '[Hardware] Impresora láser con atascos de papel recurrentes', 'La impresora láser tiene atascos de papel recurrentes.', 'El panel muestra atasco en la bandeja 2, las hojas salen arrugadas o la impresora toma varias hojas a la vez.', 'Rodillos de arrastre gastados, papel húmedo o bandeja mal ajustada a la medida del papel.', '1) Retirar el papel atascado en el sentido de avance. 2) Ventilar la resma y ajustar las guías. 3) Limpiar los rodillos con un paño humedecido en alcohol isopropílico. 4) Si continúa, solicitar el kit de mantenimiento.', '2026-10-08 10:00:00', 'Activo', true),
  (8, '[Hardware] Disco duro con ruidos y lectura lenta', 'El disco duro hace ruidos de clic y la lectura de archivos es muy lenta.', 'Archivos que tardan en abrir, errores de lectura y aviso de SMART en el arranque.', 'Falla física inminente del disco por sectores dañados o desgaste del cabezal.', '1) Respaldar de inmediato la información crítica. 2) Revisar los atributos SMART con CrystalDiskInfo. 3) Reemplazar el disco por uno nuevo. 4) Clonar o reinstalar el sistema y restaurar los datos. 5) Registrar el activo reemplazado.', '2026-10-09 11:00:00', 'Activo', true),
  (9, '[Hardware] Monitor con parpadeo intermitente', 'El monitor parpadea de forma intermitente.', 'La imagen se corta por segundos y vuelve, sobre todo con brillo alto.', 'Posible cable de video defectuoso o frecuencia de actualización mal configurada; falta confirmar.', '1) Cambiar el cable HDMI o DisplayPort. 2) Ajustar la frecuencia a 60 Hz. 3) Probar el monitor en otro equipo. Sin verificación formal del procedimiento.', '2026-10-10 12:00:00', 'Activo', false),
  (10, '[Hardware] Teclado con teclas que no responden', 'Algunas teclas del teclado no responden.', 'Ciertas letras no se escriben o se repiten.', 'Suciedad bajo las teclas o fallo de la membrana; sin diagnóstico confirmado.', '1) Limpiar con aire comprimido. 2) Reemplazar el teclado. Procedimiento descartado y sin validar.', '2026-10-11 13:00:00', 'Inactivo', false),
  (11, '[Conectividad] Sin internet y dirección IP 169.254', 'El equipo no tiene acceso a internet y el adaptador muestra una dirección 169.254.x.x.', 'Icono de red con triángulo amarillo, sin acceso a internet ni a recursos de la red interna.', 'El servidor DHCP no entregó dirección por cable desconectado, puerto del switch deshabilitado o agotamiento del rango.', '1) Revisar el cable y el puerto del switch. 2) Ejecutar ipconfig /release y ipconfig /renew. 3) Confirmar con redes que el servidor DHCP tiene direcciones libres. 4) Si persiste, asignar IP estática temporal autorizada.', '2026-10-12 14:00:00', 'Activo', true),
  (12, '[Conectividad] Wi-Fi corporativo con desconexiones frecuentes', 'El Wi-Fi corporativo se desconecta con frecuencia en una zona de la oficina.', 'Caídas cada pocos minutos, señal baja y cambios continuos entre puntos de acceso.', 'Canal saturado por interferencia o cobertura insuficiente que provoca roaming agresivo.', '1) Medir la señal y los canales con un analizador Wi-Fi. 2) Cambiar el canal del punto de acceso a uno libre. 3) Ajustar la potencia de transmisión. 4) Actualizar el controlador de la tarjeta inalámbrica. 5) Reubicar el punto de acceso si la cobertura sigue baja.', '2026-10-13 09:00:00', 'Activo', true),
  (13, '[Conectividad] VPN con error de autenticación', 'La conexión VPN falla con error de autenticación al intentar conectarse desde casa.', 'El cliente VPN muestra error 691 o se queda en verificando credenciales.', 'Contraseña vencida, hora del equipo desfasada que invalida el certificado o bloqueo del puerto por el proveedor.', '1) Verificar la fecha y hora del equipo. 2) Confirmar que la contraseña no esté vencida. 3) Cambiar el protocolo del cliente a TCP 443. 4) Reinstalar el perfil VPN. 5) Escalar a redes si el servidor registra rechazo.', '2026-10-14 10:00:00', 'Activo', true),
  (14, '[Conectividad] Sitios que no abren por nombre pero sí por IP', 'Los sitios web no abren por nombre pero responden al hacer ping a su dirección IP.', 'El navegador muestra el error DNS_PROBE_FINISHED_NXDOMAIN o nombre no resuelto.', 'Servidor DNS configurado incorrectamente en el adaptador o caché DNS dañada.', '1) Ejecutar ipconfig /flushdns. 2) Verificar los servidores DNS del adaptador. 3) Probar con nslookup contra el DNS corporativo. 4) Reiniciar el adaptador de red. 5) Reportar a redes si el DNS no responde.', '2026-10-15 11:00:00', 'Activo', true),
  (15, '[Conectividad] Configuración manual del proxy en el área administrativa', 'Configuración del proxy manual para salir a internet desde el área administrativa.', 'Navegador sin salida a internet hasta configurar el proxy en cada equipo.', 'La red anterior exigía un proxy explícito para el tráfico web.', '1) Abrir las opciones de red del navegador. 2) Escribir la dirección del proxy y el puerto 8080. Artículo inactivo: la salida a internet ahora usa configuración automática.', '2026-10-16 12:00:00', 'Inactivo', true),
  (16, '[Aplicaciones] Error 500 en aplicación web después de un despliegue', 'La aplicación web interna responde con error 500 después de un despliegue.', 'Las páginas devuelven Internal Server Error y el registro del servidor muestra excepciones de conexión a la base de datos.', 'Variable de entorno de conexión a la base de datos ausente o con valor incorrecto en el nuevo despliegue.', '1) Revisar el registro de la aplicación. 2) Comparar las variables de entorno con el ambiente anterior. 3) Corregir la cadena de conexión y reiniciar el servicio. 4) Verificar con la ruta de salud. 5) Si no se resuelve, revertir al despliegue anterior.', '2026-10-17 13:00:00', 'Activo', true),
  (17, '[Aplicaciones] Outlook sin sincronización de correo', 'Outlook no sincroniza el correo y muestra desconectado.', 'Los mensajes nuevos no llegan, la barra indica intentando conectar y aparecen mensajes en bandeja de salida.', 'Perfil de Outlook dañado o archivo de datos OST corrupto.', '1) Verificar que no esté activado el modo sin conexión. 2) Crear un perfil nuevo desde el Panel de control. 3) Renombrar el archivo OST para que se regenere. 4) Esperar la sincronización completa. 5) Confirmar el envío y la recepción de prueba.', '2026-10-18 14:00:00', 'Activo', true),
  (18, '[Aplicaciones] Excel se cierra al abrir libros con macros', 'Excel se cierra inesperadamente al abrir un libro con macros.', 'El programa deja de responder al abrir el archivo y aparece el mensaje de que Excel dejó de funcionar.', 'Complemento incompatible o macro que referencia una biblioteca no disponible.', '1) Abrir Excel en modo seguro con excel /safe. 2) Deshabilitar los complementos uno por uno. 3) Reparar la instalación de Office. 4) Revisar las referencias de la macro. 5) Guardar el libro como nuevo archivo con las macros depuradas.', '2026-10-19 09:00:00', 'Activo', true),
  (19, '[Aplicaciones] Navegador que pierde la sesión de la aplicación interna', 'El navegador no conserva la sesión de una aplicación interna y pide iniciar sesión constantemente.', 'Cada página nueva solicita credenciales otra vez.', 'Posible bloqueo de cookies de terceros o expiración muy corta de la sesión; sin confirmar.', '1) Permitir cookies para el dominio interno. 2) Limpiar la caché. 3) Probar en otro navegador. Pendiente de validación con el equipo de desarrollo.', '2026-10-20 10:00:00', 'Activo', false),
  (20, '[Aplicaciones] Error de licencia en la aplicación de nómina', 'La aplicación de nómina muestra error de licencia al iniciar.', 'Mensaje de licencia no válida al abrir el módulo de pagos.', 'Posible vencimiento de la licencia anterior; sin diagnóstico confirmado.', '1) Contactar al proveedor. 2) Reinstalar el módulo. Artículo descartado, sin verificar y sin vigencia.', '2026-10-21 11:00:00', 'Inactivo', false),
  (21, '[Servicios informáticos] Cuenta bloqueada en el directorio por intentos fallidos', 'La cuenta de usuario queda bloqueada en el directorio por intentos fallidos de contraseña.', 'Mensaje de cuenta bloqueada al iniciar sesión en el equipo o en el correo.', 'Varios intentos con contraseña incorrecta o un dispositivo móvil con credenciales antiguas.', '1) Verificar la identidad del usuario por el canal autorizado. 2) Desbloquear la cuenta en la consola del directorio. 3) Restablecer la contraseña con cambio obligatorio. 4) Actualizar la contraseña en los dispositivos móviles. 5) Revisar el origen de los intentos fallidos.', '2026-10-22 12:00:00', 'Activo', true),
  (22, '[Servicios informáticos] Acceso denegado a carpeta compartida', 'Un usuario recibe acceso denegado al abrir una carpeta compartida del servidor de archivos.', 'Mensaje de que no tiene permiso para acceder a la ruta de red, aunque otros compañeros sí entran.', 'El usuario no pertenece al grupo con permisos sobre la carpeta o los permisos heredados fueron modificados.', '1) Confirmar la ruta y el área del usuario. 2) Solicitar la aprobación del responsable de la carpeta. 3) Agregar al usuario al grupo de seguridad correspondiente. 4) Cerrar sesión y volver a entrar. 5) Registrar el cambio de permisos.', '2026-10-23 13:00:00', 'Activo', true),
  (23, '[Servicios informáticos] Copia de seguridad nocturna sin espacio', 'La copia de seguridad nocturna termina con error por espacio insuficiente.', 'El informe del trabajo de respaldo marca error de disco lleno y la última copia exitosa tiene varios días.', 'El volumen de destino alcanzó su capacidad por retención excesiva de copias antiguas.', '1) Revisar el espacio del volumen de destino. 2) Depurar las copias que superan la retención definida. 3) Ejecutar el respaldo manualmente y confirmar el éxito. 4) Ajustar la política de retención. 5) Configurar una alerta al llegar al 80 % de uso.', '2026-10-24 14:00:00', 'Activo', true),
  (24, '[Servicios informáticos] Servidor de archivos lento en horario pico', 'El servidor de archivos responde muy lento en horario pico.', 'Abrir carpetas tarda más de un minuto entre las 9 y las 11 de la mañana y se acumulan quejas de varias áreas.', 'Saturación de disco o de red por copias masivas y sincronizaciones simultáneas.', '1) Revisar el uso de disco, memoria y red con el monitor del servidor. 2) Identificar los procesos de mayor consumo. 3) Reprogramar las copias masivas a la noche. 4) Habilitar cuotas por usuario. 5) Evaluar la ampliación de la capacidad.', '2026-10-25 09:00:00', 'Activo', true),
  (25, '[Servicios informáticos] Alta de cuentas de empleados nuevos tardía', 'El alta de cuentas para empleados nuevos tarda varios días.', 'El empleado ingresa y no tiene correo ni acceso a los sistemas el primer día.', 'Falta de un procedimiento único entre recursos humanos y soporte; sin confirmar.', '1) Pedir el formulario de alta con tres días de anticipación. 2) Crear las cuentas en el directorio. 3) Entregar las credenciales por canal seguro. Procedimiento propuesto, pendiente de verificación.', '2026-10-26 10:00:00', 'Activo', false)
